(window.webpackJsonp=window.webpackJsonp||[]).push([[3],{360:function(t,e){"use strict";e.__esModule=!0,e.default={render:function(){return this.$createElement("div",{staticClass:"theme-default-content content__default lab-wide",domProps:{innerHTML:"\n<div class=\"lab-content\">\n<h1 id=\"people\"><a href=\"#people\" class=\"header-anchor\">#</a> People</h1>\n<section class=\"profile-hero\">\n  <div class=\"profile-photo\"><img src=\"/src/people/jiong%20zhang.jpg\" alt=\"Prof. Jiong Zhang\"></div>\n  <div class=\"profile-intro\">\n    <p class=\"eyebrow\">Principal Investigator</p>\n    <h2>Prof. Jiong Zhang <span>张炯</span></h2>\n    <p class=\"profile-role\">Tenured Associate Professor · School of Biomedical Engineering<br>Nanjing University, Suzhou Campus</p>\n    <div class=\"profile-tags\"><span>IEEE Senior Member</span><span>MICCAI Member</span><span>Medical Imaging AI</span></div>\n    <div class=\"profile-actions\"><a class=\"button-primary\" href=\"mailto:jiong.zhang@ieee.org\">Email</a><a href=\"https://scholar.google.com/citations?user=UJKsxKkAAAAJ&hl=en\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"button-secondary\">Google Scholar</a><a href=\"https://people.ucas.ac.cn/~jiong.zhang\" target=\"_blank\" rel=\"noopener noreferrer\" class=\"button-secondary\">UCAS Profile</a></div>\n  </div>\n</section>\n\n<section class=\"profile-stats\" aria-label=\"Academic highlights\">\n  <div><strong>80+</strong><span>peer-reviewed papers</span></div>\n  <div><strong>4</strong><span>editorial boards</span></div>\n  <div><strong>3</strong><span>major research pillars</span></div>\n</section>\n\n<h2 id=\"academic-profile\"><a href=\"#academic-profile\" class=\"header-anchor\">#</a> Academic Profile</h2>\n<p class=\"lead-copy\">Prof. Zhang develops artificial intelligence, geometric analysis, and shape-analysis methods for medical image enhancement, segmentation, registration, and biomarker extraction. His work focuses on vascular and small-vessel diseases across the eye, brain, and other organs, connecting methodological innovation with clinically meaningful imaging markers.</p>\n<p>Before joining Nanjing University, he was a professor at the Chinese Academy of Sciences in Ningbo. He received his Ph.D. from the IMAG/e group at Eindhoven University of Technology (TU/e) in 2017, continued as a postdoctoral researcher at TU/e, and in 2018 joined the Laboratory of Neuro Imaging at the Keck School of Medicine, University of Southern California.</p>\n\n<h2 id=\"research-focus\"><a href=\"#research-focus\" class=\"header-anchor\">#</a> Research Focus</h2>\n<div class=\"focus-grid\">\n  <article class=\"focus-card\"><span class=\"card-index\">01</span><h3>Medical image intelligence</h3><p>Image enhancement, pathology segmentation and detection, image registration, foundation models, multimodal learning, and medical agents.</p></article>\n  <article class=\"focus-card\"><span class=\"card-index\">02</span><h3>Vascular analysis</h3><p>2D and 3D retinal microvascular segmentation, neurovascular image analysis, and quantitative vessel biomarker extraction.</p></article>\n  <article class=\"focus-card\"><span class=\"card-index\">03</span><h3>Geometry and shape</h3><p>Vascular and cortical surface reconstruction, topology-aware modeling, intrinsic geometry, and interpretable shape analysis.</p></article>\n  <article class=\"focus-card\"><span class=\"card-index\">04</span><h3>Clinical translation</h3><p>Research on cerebrovascular and small-vessel disease, diabetic retinopathy and neuropathy, AMD, glaucoma, Alzheimer’s disease, stroke, and moyamoya disease.</p></article>\n</div>\n\n<div class=\"modality-band\"><div><span>Brain imaging</span><strong>MRI · MRA · CTA · DSA</strong></div><div><span>Ophthalmic imaging</span><strong>OCT · OCTA · Fundus · UWF · FA · AS-OCT · Confocal microscopy</strong></div></div>\n\n<h2 id=\"academic-journey\"><a href=\"#academic-journey\" class=\"header-anchor\">#</a> Academic Journey</h2>\n<div class=\"timeline\">\n  <div class=\"timeline-item\"><span>Current</span><div><h3>Nanjing University</h3><p>Tenured Associate Professor, School of Biomedical Engineering, Suzhou Campus.</p></div></div>\n  <div class=\"timeline-item\"><span>Previous</span><div><h3>Chinese Academy of Sciences</h3><p>Professor in Ningbo, China.</p></div></div>\n  <div class=\"timeline-item\"><span>2018+</span><div><h3>University of Southern California</h3><p>Postdoctoral research at the Laboratory of Neuro Imaging, Keck School of Medicine.</p></div></div>\n  <div class=\"timeline-item\"><span>2017</span><div><h3>Eindhoven University of Technology</h3><p>Ph.D. from the IMAG/e group, followed by postdoctoral research at TU/e.</p></div></div>\n</div>\n\n<h2 id=\"academic-service\"><a href=\"#academic-service\" class=\"header-anchor\">#</a> Academic Service</h2>\n<div class=\"service-grid\">\n  <article><h3>Associate editor</h3><p><em>Pattern Recognition</em>, <em>IEEE Journal of Biomedical and Health Informatics</em>, <em>Medical Physics</em>, and <em>BMJ Open Ophthalmology</em>.</p></article>\n  <article><h3>Community leadership</h3><p>Organizer of MICCAI SWITCH (2025) and SWITCH+ (2026); Area Chair or program committee member for MICCAI, ICASSP, AAAI, ICIMH, ICGIP, MICAD, and related venues.</p></article>\n  <article><h3>Special issues</h3><p>Guest editorial leadership on foundation models in medical imaging, ocular assessment for systemic disorders, and deep learning for medical image reconstruction and analysis.</p></article>\n</div>\n\n<h2 id=\"research-team\"><a href=\"#research-team\" class=\"header-anchor\">#</a> Research Team</h2>\n<div class=\"team-callout\"><div><p class=\"eyebrow\">Build with us</p><h3>Medicine, imaging, and trustworthy intelligence</h3><p>MI² Lab brings together students and collaborators in computer science, biomedical engineering, medical imaging, clinical medicine, and the life sciences.</p></div><a class=\"button-primary\" href=\"/join/\">View opportunities</a></div>\n<p class=\"roster-note\">Additional lab members will be added as the roster is finalized.</p>\n</div>"}})}}}}]);
